(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  function handleKeydown(event) {
    if (event.target && ['INPUT', 'TEXTAREA'].includes(event.target.tagName)) return;

    if (event.key === '/') {
      event.preventDefault();
      const search = document.querySelector('input[type="search"], .search input');
      if (search) search.focus();
    }

    if (event.key.toLowerCase() === 'n') {
      event.preventDefault();
      api.createCard('Quick Note', 'Jot something down...');
      api.showToast('New note created', 'info');
    }

    if (event.key === 'Tab' && event.shiftKey) {
      event.preventDefault();
      api.navigateBoards(-1);
    } else if (event.key === 'Tab') {
      event.preventDefault();
      api.navigateBoards(1);
    }
  }

  document.addEventListener('keydown', handleKeydown);
  api.showToast('Keyboard Shortcut Patch active', 'success');
})();
